export const title = "How to Plan a Vertical Laptop Stand for Closed-Lid Use";
export const metaTitle = "Vertical Laptop Stands for Closed-Lid Setups";
export const metaDescription = "Check closed-display support, laptop thickness, ventilation, port access, wake behavior, and removal before choosing a vertical stand.";
export const author = "Jamie Cole, Lead Product Researcher";
